$activeMenu='settings';require_once __DIR__.'/../Config/database.php';$pdo=(new Database())->connect();$message='';$messageType='success';
if($_SERVER['REQUEST_METHOD']==='POST'){try{$action=$_POST['action']??'general';if($action==='router'){$id=(int)($_POST['router_id']??0);$name=trim($_POST['router_name']??'');$ip=trim($_POST['ip_address']??'');$user=trim($_POST['username']??'');$port=(int)($_POST['api_port']??8728);$pass=$_POST['password']??'';if(!$id||$name===''||$ip===''||$user==='')throw new RuntimeException('Data MikroTik wajib diisi.');if($pass!==''){$s=$pdo->prepare('UPDATE router SET router_name=?,ip_address=?,username=?,password=?,api_port=? WHERE id=?');$s->execute([$name,$ip,$user,$pass,$port,$id]);}else{$s=$pdo->prepare('UPDATE router SET router_name=?,ip_address=?,username=?,api_port=? WHERE id=?');$s->execute([$name,$ip,$user,$port,$id]);}$message='Konfigurasi MikroTik berhasil disimpan.';}elseif($action==='add_router'){$name=trim($_POST['router_name']??'');$ip=trim($_POST['ip_address']??'');$user=trim($_POST['username']??'');$pass=$_POST['password']??'';$port=(int)($_POST['api_port']??8728);if($name===''||$ip===''||$user===''||$pass==='')throw new RuntimeException('Semua data router baru wajib diisi.');$s=$pdo->prepare('INSERT INTO router(router_name,ip_address,username,password,api_port,status,is_active) VALUES(?,?,?,?,?,\'OFFLINE\',0)');$s->execute([$name,$ip,$user,$pass,$port]);$message='Router baru berhasil ditambahkan.';}elseif($action==='activate_router'){$id=(int)($_POST['router_id']??0);if(!$id)throw new RuntimeException('Router tidak valid.');$pdo->beginTransaction();$pdo->exec('UPDATE router SET is_active=0');$s=$pdo->prepare('UPDATE router SET is_active=1 WHERE id=?');$s->execute([$id]);$pdo->commit();$message='Router aktif berhasil diubah. Status koneksi tetap mengikuti hasil monitoring/test.';}elseif($action==='delete_router'){$id=(int)($_POST['router_id']??0);$count=(int)$pdo->query('SELECT COUNT(*) FROM router')->fetchColumn();if($count<=1)throw new RuntimeException('Router terakhir tidak boleh dihapus.');$s=$pdo->prepare('DELETE FROM router WHERE id=?');$s->execute([$id]);$message='Router berhasil dihapus.';}else{$settings=['company_name'=>trim($_POST['company_name']??'Network Monitor'),'refresh_interval'=>max(10000,min(60000,(int)($_POST['refresh_interval']??10000))),'timezone'=>trim($_POST['timezone']??'Asia/Jakarta'),'download_warning'=>max(0,(float)($_POST['download_warning']??80)),'download_critical'=>max(0,(float)($_POST['download_critical']??90)),'upload_warning'=>max(0,(float)($_POST['upload_warning']??20)),'upload_critical'=>max(0,(float)($_POST['upload_critical']??30))];if($settings['company_name']==='')$settings['company_name']='Network Monitor';if($settings['download_critical']<=$settings['download_warning'])throw new RuntimeException('Download Critical harus lebih besar dari Download Warning.');if($settings['upload_critical']<=$settings['upload_warning'])throw new RuntimeException('Upload Critical harus lebih besar dari Upload Warning.');foreach($settings as $k=>$v){$s=$pdo->prepare('SELECT id FROM settings WHERE setting_name=? LIMIT 1');$s->execute([$k]);if($s->fetch()){$s=$pdo->prepare('UPDATE settings SET setting_value=? WHERE setting_name=?');$s->execute([(string)$v,$k]);}else{$s=$pdo->prepare('INSERT INTO settings(setting_name,setting_value) VALUES(?,?)');$s->execute([$k,(string)$v]);}}$message='Settings berhasil disimpan.';}}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$message=$e->getMessage();$messageType='danger';}}
$rows=$pdo->query('SELECT setting_name,setting_value FROM settings')->fetchAll(PDO::FETCH_KEY_PAIR);$routers=$pdo->query('SELECT * FROM router ORDER BY id ASC')->fetchAll(PDO::FETCH_ASSOC);$router=$routers[0]??[];$companyName=$rows['company_name']??'Network Monitor';$refreshInterval=(int)($rows['refresh_interval']??10000);$timezone=$rows['timezone']??'Asia/Jakarta';$downloadWarning=$rows['download_warning']??80;$downloadCritical=$rows['download_critical']??90;$uploadWarning=$rows['upload_warning']??20;$uploadCritical=$rows['upload_critical']??30;
?><!doctype html><html lang="id"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Settings - NetMonitor</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css" rel="stylesheet"><link rel="stylesheet" href="../assets/css/variables.css"><link rel="stylesheet" href="../assets/css/common.css"><link rel="stylesheet" href="../assets/css/theme.css?v=1"><link rel="stylesheet" href="../assets/css/settings.css?v=2"></head><body><?php require_once __DIR__.'/../includes/sidebar.php';?><div class="main"><div class="page-title">Settings</div><div class="page-subtitle">Pusat konfigurasi NetworkMonitor</div><?php if($message):?><div class="alert alert-<?=htmlspecialchars($messageType)?>"><i class="bi <?=$messageType==='success'?'bi-check-circle':'bi-exclamation-triangle'?> me-2"></i><?=htmlspecialchars($message)?></div><?php endif;?><div class="settings-layout"><nav class="settings-nav"><button type="button" class="active" data-settings-tab="general"><i class="bi bi-sliders"></i>General</button><button type="button" data-settings-tab="mikrotik"><i class="bi bi-router"></i>MikroTik</button><button type="button" data-settings-tab="alarm"><i class="bi bi-bell"></i>Alarm</button><button type="button" data-settings-tab="system"><i class="bi bi-cpu"></i>System</button><button type="button" data-settings-tab="billing"><i class="bi bi-whatsapp"></i>Billing</button></nav><section>
<div class="settings-pane active" data-settings-pane="general"><form method="post"><input type="hidden" name="action" value="general"><div class="settings-card"><h5><i class="bi bi-sliders me-2"></i>General Settings</h5><div class="setting-row"><div class="setting-label">Company / Application Name</div><div class="setting-description">Nama yang ditampilkan oleh aplikasi.</div><input name="company_name" class="form-control" value="<?=htmlspecialchars($companyName)?>" required></div><div class="setting-row"><div class="setting-label">Refresh Interval</div><div class="setting-description">Interval refresh minimum 10 detik agar sesuai dengan collector.</div><select name="refresh_interval" class="form-select"><option value="10000" <?=$refreshInterval===10000?'selected':''?>>10 detik</option><option value="30000" <?=$refreshInterval===30000?'selected':''?>>30 detik</option><option value="60000" <?=$refreshInterval===60000?'selected':''?>>60 detik</option></select></div><div class="setting-row"><div class="setting-label">Timezone</div><div class="setting-description">Zona waktu aplikasi.</div><select name="timezone" class="form-select"><option value="Asia/Jakarta" <?=$timezone==='Asia/Jakarta'?'selected':''?>>Asia/Jakarta (WIB)</option><option value="Asia/Makassar" <?=$timezone==='Asia/Makassar'?'selected':''?>>Asia/Makassar (WITA)</option><option value="Asia/Jayapura" <?=$timezone==='Asia/Jayapura'?'selected':''?>>Asia/Jayapura (WIT)</option></select></div><div class="settings-actions"><button class="btn btn-primary"><i class="bi bi-save me-1"></i>Simpan General</button></div></div></form></div>
<div class="settings-pane" data-settings-pane="mikrotik"><div class="settings-card"><div class="settings-card-header"><div><h2><i class="bi bi-router me-2"></i>Router Manager</h2><p>Kelola beberapa MikroTik. <strong>Active</strong> menentukan router yang dipakai modul utama, sedangkan <strong>Status</strong> menunjukkan kondisi koneksi sebenarnya.</p></div><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#addRouter"><i class="bi bi-plus-lg me-1"></i>Tambah Router</button></div><div class="table-responsive mt-4"><table class="table align-middle"><thead><tr><th>Router</th><th>IP</th><th>Port</th><th>Status</th><th>Active</th><th>Hasil Tes</th><th class="text-end">Aksi</th></tr></thead><tbody><?php foreach($routers as $r):?><tr><td><strong><?=htmlspecialchars($r['router_name'])?></strong><br><small class="text-secondary"><?=htmlspecialchars($r['username'])?></small></td><td><?=htmlspecialchars($r['ip_address'])?></td><td><?=htmlspecialchars($r['api_port'])?></td><td><span class="status-badge <?=($r['status']==='ONLINE')?'online':'offline'?> router-status-badge" data-router-id="<?=$r['id']?>"><?=htmlspecialchars($r['status'])?></span></td><td><?php if((int)$r['is_active']===1):?><span class="status-badge online"><i class="bi bi-check-circle me-1"></i>ACTIVE</span><?php else:?><span class="text-secondary small">Tidak aktif</span><?php endif;?></td><td><small class="router-connection-result text-secondary" data-router-id="<?=$r['id']?>">Belum dites</small></td><td class="text-end"><div class="btn-group btn-group-sm"><button type="button" class="btn btn-outline-info test-router-connection" data-router-id="<?=$r['id']?>" title="Test Connection"><i class="bi bi-plug"></i> Tes</button><?php if((int)$r['is_active']!==1):?><form method="post"><input type="hidden" name="action" value="activate_router"><input type="hidden" name="router_id" value="<?=$r['id']?>"><button class="btn btn-outline-success" title="Set Active"><i class="bi bi-check-circle"></i></button></form><?php endif;?><button type="button" class="btn btn-outline-primary" data-bs-toggle="modal" data-bs-target="#editRouter<?=$r['id']?>"><i class="bi bi-pencil"></i></button><?php if(count($routers)>1):?><form method="post" onsubmit="return confirm('Hapus router ini?')"><input type="hidden" name="action" value="delete_router"><input type="hidden" name="router_id" value="<?=$r['id']?>"><button class="btn btn-outline-danger"><i class="bi bi-trash"></i></button></form><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div></div><?php foreach($routers as $r):?><div class="modal fade" id="editRouter<?=$r['id']?>" tabindex="-1"><div class="modal-dialog"><form method="post" class="modal-content"><input type="hidden" name="action" value="router"><input type="hidden" name="router_id" value="<?=$r['id']?>"><div class="modal-header"><h5 class="modal-title">Edit Router</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><label class="form-label">Router Name</label><input name="router_name" class="form-control mb-3" value="<?=htmlspecialchars($r['router_name'])?>" required><label class="form-label">IP Address</label><input name="ip_address" class="form-control mb-3" value="<?=htmlspecialchars($r['ip_address'])?>" required><label class="form-label">Username</label><input name="username" class="form-control mb-3" value="<?=htmlspecialchars($r['username'])?>" required><label class="form-label">Password</label><input type="password" name="password" class="form-control mb-3" placeholder="Kosongkan = tetap"><label class="form-label">API Port</label><input type="number" name="api_port" class="form-control" value="<?=$r['api_port']?>" min="1" max="65535"></div><div class="modal-footer"><button class="btn btn-primary">Simpan</button></div></form></div></div><?php endforeach;?><div class="modal fade" id="addRouter" tabindex="-1"><div class="modal-dialog"><form method="post" class="modal-content"><input type="hidden" name="action" value="add_router"><div class="modal-header"><h5 class="modal-title">Tambah Router</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input name="router_name" class="form-control mb-3" placeholder="Router Name" required><input name="ip_address" class="form-control mb-3" placeholder="IP Address" required><input name="username" class="form-control mb-3" placeholder="API Username" required><input type="password" name="password" class="form-control mb-3" placeholder="API Password" required><input type="number" name="api_port" class="form-control" value="8728" min="1" max="65535"></div><div class="modal-footer"><button class="btn btn-primary">Tambah Router</button></div></form></div></div>
